INSERT INTO org_departments (name, description) VALUES ('Board & Governance','Board, company secretariat and governance'),('Executive Management','Executive leadership and corporate strategy'),('Finance & Administration','Finance, accounting, procurement and administration'),('Technology & Product','Engineering, product, data, AI and cybersecurity'),('Real Estate & Asset Operations','Property, land, housing and asset operations'),('Investment & Asset Management','Investment, portfolio and research functions'),('Legal, Compliance & Risk','Legal, compliance, AML/KYC, risk and controls'),('Sales, Marketing & Growth','Revenue, partnerships, marketing and community'),('Operations & Customer Success','Operations, support and quality assurance'),('Specialised Asset Divisions','Carbon, minerals, tokenization and research') ON CONFLICT (name) DO NOTHING;
INSERT INTO org_positions (title, department_id, level, status, description, responsibilities, statutory_role) SELECT 'Chief Executive Officer / Founder',id,'C-Suite','filled','Executive leadership and company strategy','Set strategy, capital allocation, governance and execution',false FROM org_departments WHERE name='Executive Management' ON CONFLICT DO NOTHING;
